using System;
using System.Collections.Generic;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Text.Json;
using System.Text.Json.Nodes;
namespace BF4Launcher;
public static class ExternalModTests {
 public static void Run(string parent,Action<bool,string> check){
  string root=Path.Combine(parent,"external-directory");
  ModManifest Manifest(string version)=>new(){Id="external-demo",Name="外部测试",Version=version,Side="local",Kind="runtime",Adapter="external",Fields=new(){new(){Id="amount",Label="倍率",Type="number",Min=1,Max=10,DefaultValue=JsonValue.Create(1)}},Runtime=new(){ApiVersion=1,Type="node",EntryPoint="main.mjs",StartWhen="launcher",Group="test.group"}};
  void Folder(string version,int amount){string path=Path.Combine(root,"mods","external-demo",version);Directory.CreateDirectory(path);Repository.Atomic(Path.Combine(path,"mod.json"),JsonSerializer.Serialize(Manifest(version),Repository.Json));File.WriteAllText(Path.Combine(path,"main.mjs"),"console.log('standalone')");Repository.Atomic(Path.Combine(path,"config.json"),"{\"amount\":"+amount+"}");}
  Folder("1.0.0",2);var repo=new Repository(root);repo.Load();check(repo.Config.Mods.Count==1&&repo.Config.Mods[0].Key=="external-demo@1.0.0","external-folder-discovered-on-start");var first=repo.Config.Mods[0];check(!first.Enabled,"external-new-folder-default-disabled");check(first.Config["amount"]!.GetValue<int>()==2,"external-module-local-config-read");check(first.Manifest.Runtime?.EntryPoint=="main.mjs","external-runtime-entry-preserved-in-model");first.Enabled=true;first.Config["amount"]=JsonValue.Create(3);repo.Save();check(JsonNode.Parse(File.ReadAllText(Path.Combine(root,first.Directory,"config.json")))!["amount"]!.GetValue<int>()==3,"external-config-window-save-writes-module-config");
  var again=new Repository(root);again.Load();check(again.Config.Mods[0].Enabled&&again.Config.Mods[0].Config["amount"]!.GetValue<int>()==3,"external-enabled-and-config-reload-preserved");Folder("1.1.0",4);check(again.RefreshModDirectory()==1&&again.Config.Mods.Count==2,"external-new-version-added-by-refresh");check(again.Config.Mods[0].Key=="external-demo@1.0.0"&&!again.Config.Mods[1].Enabled,"external-discovery-preserves-order-and-enable-state");
  var second=again.Config.Mods[1];second.Enabled=true;check(ExternalModSpec.Merge(again.Config.Mods.Where(m=>m.Enabled))["amount"]!.GetValue<int>()==4,"external-group-config-priority-bottom-wins");again.Config.Mods.Move(1,0);check(ExternalModSpec.Merge(again.Config.Mods.Where(m=>m.Enabled))["amount"]!.GetValue<int>()==3,"external-group-priority-follows-reorder");
  var invalid=Manifest("2.0.0");invalid.Runtime!.EntryPoint="../outside.exe";bool rejected=false;try{ExternalModSpec.Validate(invalid);}catch{rejected=true;}check(rejected,"external-entry-traversal-rejected");invalid.Runtime.EntryPoint="C:/outside.exe";rejected=false;try{ExternalModSpec.Validate(invalid);}catch{rejected=true;}check(rejected,"external-entry-absolute-path-rejected");invalid.Runtime.EntryPoint="main.mjs";invalid.Runtime.ApiVersion=99;rejected=false;try{ExternalModSpec.Validate(invalid);}catch{rejected=true;}check(rejected,"external-unsupported-api-version-rejected");
  invalid=Manifest("2.0.0");invalid.Runtime!.Type="executable";rejected=false;try{ExternalModSpec.EntryPath(Path.Combine(root,"mods","external-demo","1.0.0"),invalid.Runtime);}catch{rejected=true;}check(rejected,"external-entry-type-and-extension-must-match");
  string bad=Path.Combine(root,"mods","bad-config","1.0.0");Directory.CreateDirectory(bad);var badManifest=Manifest("1.0.0");badManifest.Id="bad-config";Repository.Atomic(Path.Combine(bad,"mod.json"),JsonSerializer.Serialize(badManifest,Repository.Json));File.WriteAllText(Path.Combine(bad,"main.mjs"),"");File.WriteAllText(Path.Combine(bad,"config.json"),"{bad json}");again.RefreshModDirectory();check(!again.Config.Mods.Any(m=>m.Manifest.Id=="bad-config")&&File.ReadAllText(Path.Combine(bad,"config.json"))=="{bad json}","external-invalid-config-not-overwritten-or-registered");check(again.ModDirectoryMessages.Count>0,"external-invalid-folder-has-feedback");
  string zip=Path.Combine(parent,"external-package.bf4mod");using(var z=ZipFile.Open(zip,ZipArchiveMode.Create)){void Add(string file,string text){using var w=new StreamWriter(z.CreateEntry(file).Open());w.Write(text);}Add("mod.json",JsonSerializer.Serialize(Manifest("3.0.0"),Repository.Json));Add("main.mjs","console.log('independent')");Add("config.json","{\"amount\":6}");}var imported=again.Import(zip);check(imported.Manifest.Runtime?.ApiVersion==1&&imported.Config["amount"]!.GetValue<int>()==6,"external-archive-import-preserves-code-entry-and-local-config");check(File.Exists(Path.Combine(root,imported.Directory,"main.mjs")),"external-archive-installs-execution-file-under-mod-folder");again.Remove(imported);check(!again.Config.Mods.Contains(imported),"external-remove-unregisters-module");
 }
}
